css:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: none;

  background: transparent !important;
  pointer-events: none;
}

.agitator-widget,
.agitator-widget * {
  box-sizing: border-box;
  pointer-events: none;
}

.agitator-widget {
  --agitator-border: #01524F;

  /* Rojo por defecto. */
  --agitator-fill-light: #F3C6C2;
  --agitator-fill-middle: #E69A93;
  --agitator-fill-base: #D87971;

  display: block;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;

  background: transparent;
  opacity: var(--w-opacity, 1);
  user-select: none;
}

/* BOOL = 0 */
.agitator-widget[data-state="0"] {
  --agitator-fill-light: #F3C6C2;
  --agitator-fill-middle: #E69A93;
  --agitator-fill-base: #D87971;
}

/* BOOL = 1 */
.agitator-widget[data-state="1"] {
  --agitator-fill-light: #F1FAEC;
  --agitator-fill-middle: #DDF1CF;
  --agitator-fill-base: #CCE7BB;
}

.agitator-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  shape-rendering: geometricPrecision;
}

.agitator-fill-light {
  stop-color: var(--agitator-fill-light);
}

.agitator-fill-middle {
  stop-color: var(--agitator-fill-middle);
}

.agitator-fill-base {
  stop-color: var(--agitator-fill-base);
}

.agitator-shaft {
  fill: url("#agitator-shaft-surface");
}

.agitator-connection {
  fill: none;
  stroke: var(--agitator-fill-base);
  stroke-width: 3;
  stroke-linecap: round;
}

.agitator-blade {
  fill: url("#agitator-surface");
  stroke: var(--agitator-border);
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.agitator-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 0.8;
  stroke-linecap: round;
  opacity: 0.4;
}

.agitator-shadow {
  fill: none;
  stroke: #01524F;
  stroke-width: 1;
  stroke-linecap: round;
  opacity: 0.12;
}

/* Estado inicial y BOOL = 0 */
.agitator-widget {
  --agitator-border: #8F3932;
}

.agitator-widget[data-state="0"] {
  --agitator-border: #8F3932;
}

/* BOOL = 1 */
.agitator-widget[data-state="1"] {
  --agitator-border: #47733B;
}

/* La sombra interior también acompaña al relleno. */
.agitator-shadow {
  stroke: var(--agitator-border);
}

.agitator-shaft {
  stroke: var(--agitator-border);
  stroke-width: 0.7;
  stroke-linejoin: round;
}

/* Bordes del mismo grosor en eje y aspas. */
.agitator-shaft,
.agitator-blade {
  stroke: var(--agitator-border);
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

js:
"use strict";

(function () {
  let container = null;
  let latestWidget = window.WIDGET || {};

  function isActive(value) {
    if (value === true || value === 1) {
      return true;
    }

    if (typeof value === "string") {
      const normalized = value.trim().toLowerCase();

      return (
        normalized === "1" ||
        normalized === "true"
      );
    }

    // Sin dato o valor no reconocido: rojo.
    return false;
  }

  function render(widget) {
    if (!container) {
      return;
    }

    const state = isActive(widget.value) ? "1" : "0";

    // El eje, la unión y las aspas cambian juntos.
    container.setAttribute("data-state", state);

    container.setAttribute(
      "aria-label",
      "Agitador: estado " + state
    );
  }

  window.onWidgetUpdate = function (widget) {
    latestWidget = widget || {};
    render(latestWidget);
  };

  function initialize() {
    container = document.querySelector(".agitator-widget");
    render(latestWidget);
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
